DROP TABLE IF EXISTS `audit_logs`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `audit_logs` (
  `id` varchar(36) NOT NULL,
  `event_type` varchar(100) NOT NULL,
  `source` varchar(50) NOT NULL,
  `action_taken` varchar(50) NOT NULL,
  `confidence` decimal(5,4) DEFAULT '0.0000',
  `actor` varchar(255) NOT NULL,
  `payload_summary` json DEFAULT NULL,
  `related_alert_id` varchar(36) DEFAULT NULL,
  `related_case_id` varchar(36) DEFAULT NULL,
  `related_agent_id` varchar(36) DEFAULT NULL,
  `created_at` datetime(3) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_audit_logs_event_type` (`event_type`),
  KEY `idx_audit_logs_source` (`source`),
  KEY `idx_audit_logs_action_taken` (`action_taken`),
  KEY `idx_audit_logs_related_alert_id` (`related_alert_id`),
  KEY `idx_audit_logs_related_case_id` (`related_case_id`),
  KEY `idx_audit_logs_related_agent_id` (`related_agent_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
