DROP TABLE IF EXISTS `cases`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `cases` (
  `id` varchar(36) NOT NULL,
  `alert_id` varchar(36) DEFAULT NULL,
  `title` varchar(500) NOT NULL,
  `description` text,
  `severity_num` int DEFAULT '3',
  `status` varchar(30) DEFAULT 'New',
  `assigned_to` varchar(255) DEFAULT NULL,
  `tags` json DEFAULT NULL,
  `soar_status` varchar(50) DEFAULT 'pending',
  `ai_reason` text,
  `human_approved_by` varchar(255) DEFAULT NULL,
  `confidence` decimal(5,4) DEFAULT '0.0000',
  `created_at` datetime(3) DEFAULT NULL,
  `updated_at` datetime(3) DEFAULT NULL,
  `deleted_at` datetime(3) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_cases_alert_id` (`alert_id`),
  KEY `idx_cases_severity_num` (`severity_num`),
  KEY `idx_cases_status` (`status`),
  KEY `idx_cases_deleted_at` (`deleted_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
