INSERT INTO `rules` VALUES ('FIM-001','Phát hiện thay đổi file hoặc thư mục','high','file_integrity','[{\"field\": \"action\", \"value\": \"created,modified,deleted,renamed\", \"operator\": \"in\"}]','Defense Evasion','T1564','Phát hiện file hoặc thư mục được tạo, sửa, xóa hoặc đổi tên trên endpoint.\nAlert được gửi sang SOAR để phân tích và thông báo.\n',0,'yaml_file','2026-09-08 08:20:41.702','2026-09-22 03:14:39.359',NULL),('FIM-DOWNLOAD-SUSP-001','Phát hiện file thực thi mới được tải về (Downloads Monitor)','high','file_integrity','[{\"field\": \"action\", \"value\": \"created\", \"operator\": \"equals\"}, {\"field\": \"path\", \"value\": \"Downloads,temp,.exe,.bat,.ps1,.vbs,.iso\", \"operator\": \"contains_any\"}]','Initial Access','T1566','Phát hiện file mới có định dạng thực thi được ghi nhận trong thư mục tải về.',0,'database','2026-09-19 01:14:25.640','2026-09-22 03:19:19.912',NULL),('PS-SUSPICIOUS-001','Phát hiện PowerShell thực thi lệnh mã hóa/tải file đáng ngờ','high','sysmon_process_create','[{\"field\": \"process_name\", \"value\": \"powershell.exe,pwsh.exe,powershell_ise.exe\", \"operator\": \"in\"}, {\"field\": \"command_line\", \"value\": \"-EncodedCommand,-enc ,Invoke-Expression,IEX,DownloadString,DownloadFile,Net.WebClient,Invoke-WebRequest,Start-BitsTransfer,-ExecutionPolicy Bypass,-ep bypass,-nop -w hidden\", \"operator\": \"contains_any\"}]','Execution','T1059.001','Phát hiện khi PowerShell được khởi chạy với các tham số command-line\nthường được sử dụng trong các cuộc tấn công mạng. Các dấu hiệu bao gồm:\nsử dụng EncodedCommand để ẩn giấu lệnh, Invoke-Expression (IEX) để thực\nthi code từ xa, DownloadString để tải payload malware, hoặc Bypass\nExecutionPolicy để vượt qua chính sách bảo mật hệ thống.\n',1,'database','2026-09-08 09:11:38.949','2026-09-08 09:11:38.949',NULL),('RANSOMWARE-VSS-001','Phát hiện xóa Volume Shadow Copy - Dấu hiệu Ransomware','critical','sysmon_process_create','[{\"field\": \"process_name\", \"value\": \"vssadmin.exe,wmic.exe,bcdedit.exe\", \"operator\": \"in\"}, {\"field\": \"command_line\", \"value\": \"delete shadows,shadowcopy delete,recoveryenabled No,resize shadowstorage\", \"operator\": \"contains_any\"}]','Impact','T1490','Phát hiện hành vi xóa Volume Shadow Copy bằng vssadmin.exe hoặc wmic.exe.\nĐây là kỹ thuật phổ biến của ransomware nhằm ngăn nạn nhân khôi phục\ndữ liệu từ bản sao lưu hệ thống. Hành vi này yêu cầu điều tra ngay lập tức\nvì có thể là dấu hiệu ransomware đang trong giai đoạn chuẩn bị mã hóa.\n',1,'yaml_file','2026-09-08 08:20:49.050','2026-09-08 08:20:49.827',NULL),('RULE-12','Brute focre','critical','custom_event','[{\"field\": \"event_type\", \"value\": \"custom_event\", \"operator\": \"equals\"}]','','','',1,'database','2026-09-05 15:19:41.204','2026-09-05 15:19:41.204','2026-09-08 08:22:18.676'),('RULE-NETWORK-C2','Outbound C2 Communication Pattern','medium','network_connection','[{\"field\": \"dst_ip\", \"value\": \"10.0.0.0/8\", \"operator\": \"not_equals\"}, {\"field\": \"protocol\", \"value\": \"tcp\", \"operator\": \"equals\"}]','Command and Control','T1071','Looks for suspicious outbound connections outside the internal network segmentation.',1,'database','2026-09-01 10:03:03.305','2026-09-01 10:03:03.305',NULL),('RULE-POWERSHELL-ENCODED','PowerShell Encoded Command Execution','high','process_creation','[{\"field\": \"process_name\", \"value\": \"powershell.exe\", \"operator\": \"equals\"}, {\"field\": \"command_line\", \"value\": \"-EncodedCommand\", \"operator\": \"contains\"}]','Execution','T1059.001','Detects PowerShell commands executed with encoded payloads, often used for script obfuscation.',1,'database','2026-09-01 10:03:03.292','2026-09-01 10:03:03.292',NULL),('RULE-RANSOMWARE-VSS','Ransomware VSS Shadow Delete Activity','critical','command_execution','[{\"field\": \"process_name\", \"value\": \"vssadmin.exe\", \"operator\": \"in\"}, {\"field\": \"command_line\", \"value\": \"shadow delete\", \"operator\": \"contains\"}]','Impact','T1490','Flags attempts to delete volume shadow copies, a common ransomware behavior.',1,'database','2026-09-01 10:03:03.298','2026-09-01 10:03:03.298',NULL);
